"use client";

import MainMenu from "@components/layout/main-menu";
import { useAppContext } from "@providers/AppContext";
import { useRef, useState, useEffect } from "react";
import { useTheme } from "@providers/ThemeProvider";
import Image from "next/image";

export default function Sidebar() {
  const { theme } = useTheme();
  const darkTheme = theme === "dark";

  const {
    toggleSearch,
    toggleMainMenu,
    setMainMenuVisible,
    mainMenuVisible,
    sidebarExpanded,
    toggleSidebar,
  } = useAppContext();

  const sidebarRef = useRef<HTMLDivElement | null>(null);
  const mainMenuRef = useRef<HTMLDivElement | null>(null);
  const mainMenuToggleBtnRef = useRef<HTMLDivElement | null>(null);
  const [mainMenuLeft, setMainMenuLeft] = useState<number | null>(null);

  // Sidebar empty-area click (ONLY when collapsed)
  const handleSidebarClick = (e: React.MouseEvent) => {
    if (!sidebarExpanded) {
      const target = e.target as HTMLElement;

      // Ignore clicks on buttons, icons, links
      if (target.closest("button, i, a")) return;

      toggleSidebar();
    }
  }

  // MoreBar positioning
  useEffect(() => {
    if (mainMenuToggleBtnRef.current) {
      const rect = mainMenuToggleBtnRef.current.getBoundingClientRect();
      setMainMenuLeft(window.innerWidth - rect.left - 100);
    }
  }, [mainMenuVisible, mainMenuToggleBtnRef.current]);

  // Close MoreBar on outside click
  useEffect(() => {
    const closeIfOutside = (e: MouseEvent) => {
      if (
        mainMenuVisible &&
        mainMenuRef.current &&
        !mainMenuRef.current.contains(e.target as Node) &&
        !mainMenuToggleBtnRef.current?.contains(e.target as Node)
      ) {
        setMainMenuVisible(false);
      }
    };
    window.addEventListener("click", closeIfOutside);
    return () => window.removeEventListener("click", closeIfOutside);
  }, [mainMenuVisible]);

  const sidebarItems = [
    {
      label: "New Chat",
      icon: <i className="bx bx-edit text-text text-xl" />,
      onClick: null,
    },
    {
      label: "Search Chat",
      icon: <i className="bx bx-search text-text text-xl" />,
      onClick: toggleSearch,
    },
  ];

  return (
    <div
      ref={sidebarRef}
      onClick={handleSidebarClick}
      className={`
        relative h-full bg-bg flex flex-col
        transition-all duration-500 ease-in-out
        ${sidebarExpanded ? "w-[260px]" : "cursor-w-resize w-[60px]"}
      `}
    >
      {/* Logo + Collapse Button */}
      <div className="p-4 flex items-center justify-between">
        <Image
          src={`/logos/${darkTheme ? "white_triangle" : "black_triangle"}.png`}
          alt="Woah AI"
          width={30}
          height={30}
        />
        {sidebarExpanded && (
          <div className="text-text transition hover:bg-bg-hover rounded-full cursor-pointerw-[25px] h-[25px]">
            <button
              onClick={toggleSidebar}
              className="cursor-pointer w-[25px] h-[25px] flex items-center justify-center"
            >
              <i className="bx bx-chevron-left text-xl"/>
            </button>
          </div>
        )}
      </div>

      {/* Menu */}
      <div className="flex-1 flex flex-col justify-between px-2 py-4">
        <div className="flex flex-col gap-4">
          {sidebarItems.map((item, idx) => (
            <div
              key={idx}
              className="flex items-center gap-3 px-3 cursor-pointer text-text"
              onClick={item.onClick || undefined}
            >
              {item.icon}
              <span
                className={`text-sm font-medium truncate transition-opacity duration-300
                  ${sidebarExpanded ? "opacity-100" : "opacity-0"}
                `}
              >
                {item.label}
              </span>
            </div>
          ))}
        </div>

        {/* Profile */}
        <div
          ref={mainMenuToggleBtnRef}
          className="flex px-3 items-center gap-3 cursor-pointer text-text"
          onClick={toggleMainMenu}
        >
          <i className="bx bx-user text-xl" />
          <span
            className={`text-sm font-medium truncate transition-opacity duration-300
              ${sidebarExpanded ? "opacity-100" : "opacity-0"}
            `}
          >
            My Profile
          </span>
        </div>
      </div>

      {/* Main Menu
      {mainMenuVisible && mainMenuLeft !== null && (
        <div
          ref={mainMenuRef}
          className="absolute"
          style={{ top: "60px", right: `${mainMenuLeft}px` }}
        >
          <MainMenu onClickToggle={() => setMainMenuVisible(false)} />
        </div>
      )}*/}
  </div>);
}
